// Go-live lane H1, in the browser: the PRODUCTION build behind the REAL Hoy server, a fake Clerk and a fake Company OS
// plus a fake storage (both on 127.0.0.1; fictional data, generated bytes). Node half: scripts/test-golive-images.mjs.
// - A teacher's bio, specialties and photo show to a signed-out visitor; a teacher with none renders; hostile text stays
//   text; a photo the policy refuses (a former coach's) renders as no photo, never a broken image.
// - Class schedule › Teachers: the real upload (POST /files, PUT, confirm), save, then the old file deleted; it shows on the site.
// - Settings › Payments: the QR upload; a refused upload says why in words; a failed delete shows no error.
// - The content page's notice points to Class schedule.
// Run: npm run build:production && QA_PROD_DIST=dist node scripts/test-golive-images-ui.mjs
import { createServer } from 'node:http';
import { deflateSync } from 'node:zlib';
import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { launchBrowser, reporter } from './lib/launch-qa.mjs';
import { cosFilter } from './lib/cos-filter.mjs';
import { createHandler, createHoyServer } from '../server/app.mjs';
import { loadConfig } from '../server/config.mjs';

const { check, done } = reporter('go-live images (UI)');
const DIST = resolve(process.env.QA_PROD_DIST ?? 'dist');
if (!existsSync(join(DIST, 'index.html')) || !readdirSync(join(DIST, 'assets')).filter((f) => f.endsWith('.js')).some((f) => readFileSync(join(DIST, 'assets', f), 'utf8').includes('clerk-js'))) {
  console.error(`${DIST} is not a production build: run npm run build:production (or set QA_PROD_DIST)`); process.exit(1);
}
const TENANT = 'hoy-img';
const HOST = 'fake.clerk.accounts.dev';
const PK = `pk_test_${Buffer.from(`${HOST}$`).toString('base64')}`;
const FAKE_CLERK = readFileSync(new URL('./fixtures/fake-clerk.js', import.meta.url), 'utf8');
const READ_TOKEN = `cos_svc_5d1e2f3a-4b5c-4d6e-8f70-8192a3b4c5d6_${'Q'.repeat(43)}`;
const XSS = '<img src=x onerror="window.__xss=1"> hola';

/** A real 1×1 PNG, so `naturalWidth` proves the bytes arrived. */
function onePixel() {
  const crcTable = Array.from({ length: 256 }, (_, n) => { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; return c >>> 0; });
  const crc = (b) => { let c = 0xffffffff; for (const x of b) c = crcTable[(c ^ x) & 255] ^ (c >>> 8); return (c ^ 0xffffffff) >>> 0; };
  const chunk = (type, data) => { const t = Buffer.concat([Buffer.from(type), data]); const len = Buffer.alloc(4); len.writeUInt32BE(data.length); const sum = Buffer.alloc(4); sum.writeUInt32BE(crc(t)); return Buffer.concat([len, t, sum]); };
  const head = Buffer.alloc(13); head.writeUInt32BE(1, 0); head.writeUInt32BE(1, 4); head[8] = 8; head[9] = 2;
  return Buffer.concat([Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]), chunk('IHDR', head), chunk('IDAT', deflateSync(Buffer.from([0, 200, 80, 40]))), chunk('IEND', Buffer.alloc(0))]);
}
const PNG = onePixel();

const uuid = (n) => `00000000-0000-4000-8000-${String(n).padStart(12, '0')}`;
const at = '2026-10-01T12:00:00.000Z';
const rec = (id, data) => ({ id, data, orgUnitId: null, createdAt: at, updatedAt: at });
const IDS = { oldPhoto: uuid(101), formerPhoto: uuid(102), oldQr: uuid(103) };
let world;
function reset(flags = {}) {
  const map = (rows) => new Map(rows.map((r) => [r.id, r]));
  let seq = 500;
  world = {
    flags, log: [], nextId: () => uuid(++seq),
    person: map([rec('p_clara', { name: 'Clara Zuluaga' }), rec('p_nora', { name: 'Nora Prueba' }), rec('p_xss', { name: 'Tomás Hostil' }), rec('p_former', { name: 'Lía Antes' })]),
    coach: map([
      rec('co_clara', { person: 'p_clara', kind: 'teacher', active: true, bio: { es: 'Guía Fuego con calma.', en: 'Guides Fuego calmly.' }, specialties: ['fuego'], photo: IDS.oldPhoto }),
      rec('co_nora', { person: 'p_nora', kind: 'teacher', active: true }),
      rec('co_xss', { person: 'p_xss', kind: 'teacher', active: true, bio: { es: XSS, en: XSS }, specialties: ['<script>', 7], photo: 'javascript:alert(1)' }),
      rec('co_former', { person: 'p_former', kind: 'teacher', active: true, photo: IDS.formerPhoto }),
    ]),
    resource: map([]), schedule: map([]), occurrence: map([]), product: map([]), hours_override: map([]), booking: map([]),
    setting: map([rec('set_pub', { key: 'studio_settings', value: { payments: { bankName: 'BANCO FICTICIO', accountType: 'savings', accountNumber: 'TEST-1', accountHolder: 'HOY', qrImageUrl: `/media/${IDS.oldQr}`, breBKey: 'TEST', wompiEnv: 'sandbox' } } })]),
    /** Files the policy shows the read identity. The former coach's is not among them. */
    published: new Set([IDS.oldPhoto, IDS.oldQr]),
    file: new Map(),
  };
}
reset();
const json = (res, status, body) => { res.writeHead(status, { 'content-type': 'application/json' }); res.end(body === undefined ? '' : JSON.stringify(body)); };
const PEOPLE = {
  user_admin: { name: 'Mateo Admin', person: null, keys: ['administrator', 'super_admin'], superAdmin: true },
  user_customer: { name: 'Ana Cliente', person: 'p_ana', keys: ['member'], superAdmin: false },
};
const ACCOUNTS = { 'admin@example.test': { userId: 'user_admin', firstName: 'Mateo' }, 'cliente@example.test': { userId: 'user_customer', firstName: 'Ana' } };
const userOf = (req) => /^Bearer fake\.([^.]+)\.[^.]+$/.exec(req.headers.authorization ?? '')?.[1] ?? null;

// ── fake storage ─────────────────────────────────────────────────────────────────────────────────────────────────
const storageSeen = [];
const storage = createServer((req, res) => {
  const cors = { 'access-control-allow-origin': '*', 'access-control-allow-methods': 'PUT,GET', 'access-control-allow-headers': 'content-type' };
  if (req.method === 'OPTIONS') { res.writeHead(204, cors); return res.end(); }
  storageSeen.push(`${req.method} ${req.url}`);
  req.resume();
  req.on('end', () => {
    if (req.method === 'PUT') { res.writeHead(200, cors); return res.end(); }
    res.writeHead(200, { 'content-type': 'image/png', 'content-length': PNG.length }); res.end(PNG);
  });
});
await new Promise((r) => storage.listen(0, '127.0.0.1', r));
const STORAGE = `http://127.0.0.1:${storage.address().port}`;

// ── fake Company OS ──────────────────────────────────────────────────────────────────────────────────────────────
const cos = createServer((req, res) => {
  let raw = '';
  req.on('data', (c) => { raw += c; });
  req.on('end', () => {
    const path = new URL(req.url, 'http://cos').pathname.replace(`/t/${TENANT}`, '');
    const body = raw ? JSON.parse(raw) : undefined;
    const reader = req.headers.authorization === `Bearer ${READ_TOKEN}`;
    world.log.push({ method: req.method, path, body, reader });
    const links = path.match(/^\/public-files\/([^/]+)\/url$/);
    if (links) return world.published.has(links[1]) ? json(res, 200, { url: `${STORAGE}/obj/${links[1]}?token=signed`, expiresIn: 60 }) : json(res, 404, { error: 'not found' });
    if (path === '/me') { const p = PEOPLE[userOf(req)]; return p ? json(res, 200, { tenant: { slug: TENANT, timezone: 'America/Bogota' }, user: { id: userOf(req), name: p.name, email: `${userOf(req)}@example.test` }, roleKeys: p.keys, isSuperAdmin: p.superAdmin, caps: [], personId: p.person }) : json(res, 401, { error: 'unauthorized' }); }
    if (path === '/query') {
      const rows = world[body.entity];
      if (!rows || rows === world.file) return json(res, 200, { data: [] });
      const out = [...rows.values()].filter((r) => cosFilter(r, body.filter, userOf(req))).map((r) => structuredClone(r));
      for (const inc of body.include ?? []) for (const r of out) { const t = world.person.get(r.data[inc.field]); if (t) r.data[inc.field] = { id: t.id, name: t.data.name }; }
      return json(res, 200, { data: out.slice(body.offset ?? 0, (body.offset ?? 0) + (body.limit ?? 100)) });
    }
    if (reader) return json(res, 403, { error: 'read_only_identity' });
    if (path === '/files' && req.method === 'POST') {
      if (world.flags.refuseUpload) return json(res, 403, { error: 'forbidden' });
      if (!['image/png', 'image/jpeg', 'image/webp'].includes(body.mime)) return json(res, 422, { error: 'file_type_not_allowed' });
      const id = world.nextId(); world.file.set(id, body);
      return json(res, 201, { file: { id, ...body, status: 'pending' }, uploadUrl: `${STORAGE}/upload/${id}` });
    }
    const confirm = path.match(/^\/files\/([^/]+)\/confirm$/);
    if (confirm) { world.published.add(confirm[1]); return json(res, 200, { file: { id: confirm[1], data: { status: 'ready', published: true } } }); }
    const del = path.match(/^\/api\/file\/([^/]+)$/);
    if (del && req.method === 'DELETE') { if (world.flags.refuseDelete) return json(res, 403, { error: 'forbidden' }); world.published.delete(del[1]); return json(res, 200, {}); }
    if (path === '/batch') {
      const ids = body.ops.map((o) => { const r = world[o.entity]?.get(o.id); if (r) Object.assign(r.data, o.data); return o.id ?? world.nextId(); });
      return json(res, 200, { ids });
    }
    const setting = path.match(/^\/api\/setting\/([^/]+)$/);
    if (setting && req.method !== 'GET') { const r = world.setting.get(setting[1]); if (r) Object.assign(r.data, body); return json(res, 200, { data: r }); }
    return json(res, req.method === 'GET' ? 200 : 404, req.method === 'GET' ? { data: [] } : { error: 'not_found' });
  });
});
await new Promise((r) => cos.listen(0, '127.0.0.1', r));

// ── the real Hoy server ──────────────────────────────────────────────────────────────────────────────────────────
const config = loadConfig({
  COMPANY_OS_URL: `http://127.0.0.1:${cos.address().port}`, COMPANY_OS_TENANT: TENANT, CLERK_SECRET_KEY: 'sk_test_example',
  CLERK_PUBLISHABLE_KEY: PK, HOY_ENV: 'local', DIST_DIR: DIST, SITE_LIVE: 'true', COMPANY_OS_READ_TOKEN: READ_TOKEN,
});
const web = createHoyServer(await createHandler(config, {
  verifySession: async (token) => { const m = /^fake\.([^.]+)\./.exec(token); if (!m) throw new Error('invalid'); return { userId: m[1] }; },
  log: () => {},
}));
await new Promise((r) => web.listen(Number(process.env.QA_PORT ?? 5241), '127.0.0.1', r));
const BASE = `http://127.0.0.1:${web.address().port}`;

const browser = await launchBrowser();
const errors = [];
async function context(lang = 'es') {
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 900 }, reducedMotion: 'reduce', timezoneId: 'America/Bogota' });
  await ctx.route(/^https?:\/\/(?!127\.0\.0\.1)/, (r) => r.abort());
  await ctx.route(`https://${HOST}/npm/@clerk/clerk-js@*/dist/clerk.browser.js`, (r) => r.fulfill({ status: 200, contentType: 'text/javascript', body: FAKE_CLERK }));
  await ctx.addInitScript(({ accounts, pk, lang }) => {
    window.__fakeClerkConfig = { accounts, publishableKey: pk };
    if (!sessionStorage.getItem('qa-init')) { sessionStorage.setItem('qa-init', '1'); localStorage.setItem('hoyos.lang', lang); }
  }, { accounts: ACCOUNTS, pk: PK, lang });
  const page = await ctx.newPage();
  page.on('pageerror', (e) => errors.push(e.message));
  return { ctx, page };
}
async function site(path, lang) {
  const { ctx, page } = await context(lang);
  await page.goto(`${BASE}/#${path}`);
  await page.locator('.site-main').waitFor();
  await page.waitForTimeout(1500);
  return { ctx, page };
}
async function signedIn(email) {
  const { ctx, page } = await context();
  await page.goto(`${BASE}/#/auth/sign-in`);
  await page.waitForTimeout(800);
  await page.locator('[data-step="email"] input').fill(email);
  await page.locator('[data-step="email"] button[type=submit]').click();
  await page.locator('[data-step="code"]').waitFor({ timeout: 5000 });
  await page.locator('[data-step="code"] input').fill('424242');
  await page.locator('[data-step="code"] button[type=submit]').click();
  await page.waitForTimeout(1500);
  return { ctx, page };
}
const go = async (page, path) => { await page.goto(`${BASE}/#${path}`); await page.waitForTimeout(1200); };
const framesOf = (page) => page.locator('.site-teacher-frame');
const frame = (page, name) => framesOf(page).filter({ hasText: name });
const loaded = (locator) => locator.evaluate((img) => img.complete && img.naturalWidth > 0);
const file = (name = 'foto.png', mimeType = 'image/png') => ({ name, mimeType, buffer: PNG });

try {
  // ── signed out ───────────────────────────────────────────────────────────────────────────────────────────────
  let { ctx, page } = await site('/site/teachers');
  check('site: a teacher\'s bio from Company OS shows', (await frame(page, 'Clara Zuluaga').innerText()).includes('Guía Fuego con calma.'));
  const clara = frame(page, 'Clara Zuluaga').locator('img').first();
  check('site: a teacher\'s photo comes from /media/<id> and really loads', (await clara.getAttribute('src')) === `/media/${IDS.oldPhoto}` && await loaded(clara));
  check('site: a teacher\'s specialty shows', /Fuego/.test(await frame(page, 'Clara Zuluaga').innerText()));
  check('site: a teacher with no bio or photo renders, with the pending portrait', await frame(page, 'Nora Prueba').locator('.site-teacher-monogram').count() === 1);
  const hostile = await frame(page, 'Tomás Hostil').innerText();
  check('site: hostile text is shown as text and runs nothing', hostile.includes('<img src=x') && !(await page.evaluate(() => window.__xss)) && await frame(page, 'Tomás Hostil').locator('img[src="x"]').count() === 0);
  check('site: a hostile stored photo is no photo', await frame(page, 'Tomás Hostil').locator('.site-teacher-monogram').count() === 1);
  check('site: a photo the policy refuses renders as no photo, never a broken image', await frame(page, 'Lía Antes').locator('.site-teacher-monogram').count() === 1 && await frame(page, 'Lía Antes').locator('img').count() === 0);
  await ctx.close();
  ({ ctx, page } = await site('/site/teachers', 'en'));
  check('site (en): the English bio', (await frame(page, 'Clara Zuluaga').innerText()).includes('Guides Fuego calmly.'));
  await ctx.close();
  ({ ctx, page } = await site('/site'));
  check('home: no teacher image is broken', await page.locator('.sanctuary-teacher-photo').evaluateAll((imgs) => imgs.every((i) => !i.complete || i.naturalWidth > 0)));
  await ctx.close();

  // ── Class schedule › Teachers ────────────────────────────────────────────────────────────────────────────────
  reset();
  ({ ctx, page } = await signedIn('admin@example.test'));
  await go(page, '/admin/class-schedule');
  await page.getByRole('button', { name: 'Profesores' }).or(page.getByText('Profesores', { exact: true })).first().click();
  await page.locator('[class*=card]').filter({ hasText: 'Clara Zuluaga' }).getByRole('button', { name: 'Editar' }).click();
  await page.getByLabel('Biografía (español)').fill('Nueva bio de Clara.');
  await page.getByLabel('Biografía (inglés)').fill('Clara\'s new bio.');
  await page.getByText('Pulso', { exact: true }).first().click();
  const field = page.locator('.shared-image-field');
  await field.getByRole('button', { name: 'Subir imagen' }).click();
  await field.locator('input[type=file]').setInputFiles(file());
  await field.getByRole('button', { name: 'Usar esta foto' }).click();
  await page.getByRole('button', { name: 'Guardar' }).click();
  await page.waitForTimeout(1200);
  const seq = world.log.filter((l) => ['/files', '/batch'].includes(l.path) || /\/confirm$|^\/api\/file\//.test(l.path)).map((l) => (l.path.startsWith('/api/file/') ? 'delete' : l.path.endsWith('/confirm') ? 'confirm' : l.path));
  check('teacher: POST /files, confirm, save, then the old file is deleted, in that order', seq.join() === '/files,confirm,/batch,delete', seq.join());
  check('teacher: the file went to storage with a PUT', storageSeen.some((s) => s.startsWith('PUT /upload/')));
  const saved = world.coach.get('co_clara').data;
  check('teacher: bio, slugs and the bare photo id are saved', saved.bio.es === 'Nueva bio de Clara.' && saved.specialties.includes('pulso') && /^[0-9a-f-]{36}$/.test(saved.photo) && saved.photo !== IDS.oldPhoto, JSON.stringify(saved));
  check('teacher: the old file is gone', !world.published.has(IDS.oldPhoto));
  await go(page, '/admin/content');
  await page.getByText(/Profesores|Teachers/).first().click().catch(() => {});
  check('content page: the notice points to Class schedule', await page.getByText('Horario de clases › Profesores').count() > 0);
  await ctx.close();
  ({ ctx, page } = await site('/site/teachers'));
  check('site: the saved teacher shows to a signed-out visitor', (await frame(page, 'Clara Zuluaga').innerText()).includes('Nueva bio de Clara.') && await loaded(frame(page, 'Clara Zuluaga').locator('img').first()));
  await ctx.close();

  // ── Settings › Payments ──────────────────────────────────────────────────────────────────────────────────────
  reset({ refuseDelete: true });
  ({ ctx, page } = await signedIn('admin@example.test'));
  await go(page, '/admin/settings/payments');
  const qr = page.locator('.shared-image-field');
  await qr.getByRole('button', { name: 'Subir imagen' }).click();
  await qr.locator('input[type=file]').setInputFiles(file('foto.gif', 'image/gif'));
  await qr.getByRole('alert').waitFor({ timeout: 5000 });
  check('QR: a wrong type is refused in words', /JPEG, PNG o WebP/.test(await qr.getByRole('alert').innerText()));
  await qr.locator('input[type=file]').setInputFiles(file('qr.png'));
  await qr.getByRole('button', { name: 'Usar esta foto' }).click();
  await page.getByRole('button', { name: /Guardar/ }).first().click();
  await page.waitForTimeout(1200);
  const qrUrl = world.setting.get('set_pub').data.value?.payments?.qrImageUrl ?? '';
  check('QR: saved as /media/<id> on the public settings record, owned by it', /^\/media\/[0-9a-f-]{36}$/.test(qrUrl) && qrUrl !== `/media/${IDS.oldQr}` && [...world.file.values()].some((f) => f.ownerEntity === 'setting' && f.ownerId === 'set_pub' && f.kind === 'image'), qrUrl);
  check('QR: a failed delete shows no error, the new image stands', await page.getByText('No tienes permiso').count() === 0);
  const signedOut = await browser.newContext();
  check('QR: a signed-out visitor gets the image', (await signedOut.request.get(`${BASE}${qrUrl}`)).status() === 200);
  await signedOut.close();
  const customerSees = await page.evaluate(async (u) => (await fetch(u)).status, qrUrl);
  check('QR: so does a signed-in person, with no token on the request', customerSees === 200);
  await ctx.close();

  reset({ refuseUpload: true });
  ({ ctx, page } = await signedIn('admin@example.test'));
  await go(page, '/admin/settings/payments');
  const refused = page.locator('.shared-image-field');
  await refused.getByRole('button', { name: 'Subir imagen' }).click();
  await refused.locator('input[type=file]').setInputFiles(file('qr.png'));
  await refused.getByRole('alert').waitFor({ timeout: 5000 });
  check('QR: a 403 says so in words', /No tienes permiso/.test(await refused.getByRole('alert').innerText()));
  await ctx.close();
} finally {
  check('no page threw', errors.length === 0, errors.join(' | '));
  await browser.close();
  web.close(); cos.close(); storage.close();
}
done();
